// 家庭有限页直接读取当前玩家索引及已可见亲属，不导出世界、不重算收养和继任资格。
#include "family_model.hpp"
#include "resident/views/common_presentation.hpp"
#include "resident/views/character_presentation.hpp"
namespace hanmo::resident {
namespace {
using namespace boundary;
// 父母、指定人与子女都由家庭永久来源选择；头像失败作为单人物错误留在原槽位。
template<class T> const T* find_fact(const FamilyState& s,const StableId& id){auto* f=s.facts.find(id);return f?std::get_if<T>(f):nullptr;}
BoundaryValue portrait(const CommonStore& c,const CommonCatalog& catalog,const StableId& actor){CommonCharacterPresentation source(c.state(),catalog);auto view=source.character(actor);if(!view.ok)return obj({{"ok",{false}},{"code",{view.error.original.code}}});auto out=encode_character_presentation(view.value);return out.ok?std::move(out.value):obj({{"ok",{false}},{"code",{out.error.original.code}}});}
StableId place(const CommonStore& c,const StableId& actor){auto at=c.resolved_location(actor);auto* p=at.ok?std::get_if<SettlementLocation>(&at.value):nullptr;return p?p->place_id:StableId{};}
Integer age(const CommonStore& c,const StableId& actor){auto* a=c.state().actors.find(actor);return a&&a->birth_tick&&*a->birth_tick>=-2147483647&&*a->birth_tick<=c.tick()?(c.tick()-*a->birth_tick)/720:-1;}
// 仅选择本地作者原序的首服务岗位；即使禁用也保留该原上下文供preview拒绝。
BoundaryValue provider(const CommonStore& c,const CommonCatalog& catalog){auto here=place(c,c.state().metadata.player_actor_id);for(const auto& row:catalog.roles.rows())if(row.second.place_id==here&&std::find(row.second.services.begin(),row.second.services.end(),"family_adopt")!=row.second.services.end()){auto* role=c.state().roles.find(row.first);if(!role)return obj({});return interaction_codec::encode_context({row.second.place_id,role->actor_id,row.first});}return obj({});}
}
// 原页面以缺省或空字典表示没有办理岗位；仅非空上下文进入完整字段解码，不替调用者另选人物。
Outcome<BoundaryValue> query_family_view(const CommonStore& c,const FamilyState& family,const CommonCatalog& catalog,const StableId& query,const BoundaryValue& args,const FamilyRestRows& rest_rows){try{using namespace boundary;if(query=="family_provider_context"){fields(args,{}, {},"args");return {true,provider(c,catalog),{}};}if(query!="family_page")return {false,{},common_failure("UnsupportedLiveQuery",query,ErrorKind::unsupported_capability).error};fields(args,{}, {"tab","provider_context"},"args");auto tab=args.find("tab")?get_string(args,"tab","args"):StableId("family");InteractionContext context;if(auto* input=args.find("provider_context");input&&!object(*input,"args/provider_context").empty())context=interaction_codec::decode_context(*input,"args/provider_context");const auto& id=c.state().metadata.player_actor_id;auto* actor=c.actor(id);if(!actor)return {false,{},common_failure("UnknownActor").error};CommonPresentation presentation(c.state(),catalog);auto name=[&](const StableId& person){auto result=presentation.display_name(person);return result.ok?result.value:StableId{};};auto* action=c.action(actor->action_id);BoundaryValue guardian=obj({}),heir=obj({}),activity=obj({});if(auto* source=family.children.find(id))if(auto* adoption=find_fact<AdoptionFact>(family,*source))guardian=obj({{"display_name",{name(adoption->guardian_actor_id)}}});if(auto* source=family.designations.find(id))if(auto* choice=find_fact<FamilyChoice>(family,*source))if(!choice->heir_actor_id.empty())heir=obj({{"actor_id",{choice->heir_actor_id}},{"display_name",{name(choice->heir_actor_id)}}});if(action)activity=obj({{"kind",{action->kind}},{"remaining_ticks",{action->remaining_ticks}}});auto view=obj({{"actor_id",{id}},{"display_name",{name(id)}},{"age_years",{age(c,id)}},{"place_id",{place(c,id)}},{"hp",{actor->hp}},{"fatigue",{actor->fatigue}},{"portrait_input",portrait(c,catalog,id)},{"guardian",std::move(guardian)},{"heir",std::move(heir)},{"action",std::move(activity)}});auto& rows=std::get<BoundaryValue::Dict>(view.data);if(tab=="rest"){if(!rest_rows)return {false,{},common_failure("UnsupportedNativeCapability","family_rest_rows",ErrorKind::unsupported_capability).error};auto rest=rest_rows(id);if(!rest.ok)return rest;if(!rest.value.as<BoundaryValue::Array>())return {false,{},common_failure("InvalidFamilyRestRows").error};rows.emplace_back("estates",std::move(rest.value));return {true,std::move(view),{}};}
    std::vector<StableId> ids;for(const auto& child:family.children.rows()){auto* f=find_fact<AdoptionFact>(family,child.second);if(f&&f->kind=="family_adoption"&&f->guardian_actor_id==id&&f->success&&c.actor(child.first))ids.push_back(child.first);}std::sort(ids.begin(),ids.end());BoundaryValue::Array children;auto here=c.resolved_location(id);auto* a=here.ok?std::get_if<SettlementLocation>(&here.value):nullptr;for(const auto& child:ids){auto* f=find_fact<AdoptionFact>(family,*family.children.find(child));auto* person=c.actor(child);auto there=c.resolved_location(child);auto* b=there.ok?std::get_if<SettlementLocation>(&there.value):nullptr;children.push_back(obj({{"actor_id",{child}},{"display_name",{name(child)}},{"age_years",{age(c,child)}},{"heir_min_age",{f->terms.policy.heir_min_age}},{"place_id",{b?b->place_id:StableId{}}},{"together",{a&&b&&a->place_id==b->place_id&&a->settlement_id==b->settlement_id}},{"alive",{person->alive}},{"busy",{!person->action_id.empty()}},{"portrait_input",portrait(c,catalog,child)}}));}rows.emplace_back("children",BoundaryValue{std::move(children)});BoundaryValue adoption=obj({});auto* role=catalog.roles.find(context.role_id);if(role&&std::find(role->services.begin(),role->services.end(),"family_adopt")!=role->services.end()){bool pending=action&&action->kind=="family_adopt";adoption=obj({{"pending",{pending}}});if(!pending){auto& fields=std::get<BoundaryValue::Dict>(adoption.data);fields.emplace_back("context",interaction_codec::encode_context(context));fields.emplace_back("provider_display_name",BoundaryValue{name(context.provider_actor_id)});}}rows.emplace_back("adoption",std::move(adoption));return {true,std::move(view),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
} // 页面不返回家庭私密创建条款、资产转移账本或原始人物记录。
